using System.Text;

namespace Invoicing;

/// <summary>Renders an invoice to a plain-text document.</summary>
public sealed class InvoiceRenderer
{
    public string Render(Invoice invoice, Account account)
    {
        var sb = new StringBuilder();

        AppendHeader(sb, invoice, account);
        var (net, vat) = AppendInvoiceLines(sb, invoice);
        AppendTotals(sb, net, vat, account.Kind);
        AppendPaymentTerms(sb, account.Kind);

        return sb.ToString();
    }

    private static void AppendHeader(StringBuilder sb, Invoice invoice, Account account)
    {
        sb.AppendLine($"INVOICE {invoice.Number}");
        if (account.Name.Length > 0)
            sb.AppendLine(account.Name);

        var accountDescription = account.Kind switch
        {
            AccountKind.Business => "VAT registered",
            AccountKind.Government => "Government purchase order",
            AccountKind.Consumer => "Consumer",
            _ => null
        };

        if (accountDescription is not null)
            sb.AppendLine(accountDescription);
    }

    private static (decimal Net, decimal Vat) AppendInvoiceLines(
        StringBuilder sb,
        Invoice invoice)
    {
        decimal net = 0m;
        decimal vat = 0m;

        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m)
                continue;

            var lineVat = line.NetAmount * line.VatRate;
            var rateDescription = GetRateDescription(line.VatRate, lineVat);
            sb.AppendLine($"{line.Description} {line.NetAmount} ({rateDescription})");

            net += line.NetAmount;
            vat += lineVat;

            if (line.Description.Length > 40)
                sb.AppendLine("  (description truncated)");
        }

        return (net, vat);
    }

    private static string GetRateDescription(decimal vatRate, decimal lineVat)
    {
        if (vatRate == 0m)
            return "zero-rated";

        return vatRate >= 0.2m
            ? $"std {lineVat}"
            : $"reduced {lineVat}";
    }

    private static void AppendTotals(
        StringBuilder sb,
        decimal net,
        decimal vat,
        AccountKind accountKind)
    {
        var discount = CalculateDiscount(net, accountKind);
        var gross = decimal.Max(0m, net + vat - discount);
        sb.AppendLine($"NET {net} VAT {vat} DISC {discount} TOTAL {gross}");
    }

    private static decimal CalculateDiscount(decimal net, AccountKind accountKind)
    {
        if (net > 1000m && accountKind == AccountKind.Business)
            return net * 0.05m;

        return net > 5000m ? net * 0.10m : 0m;
    }

    private static void AppendPaymentTerms(StringBuilder sb, AccountKind accountKind)
    {
        var paymentDays = accountKind == AccountKind.Government ? 30 : 14;
        sb.AppendLine($"Remit within {paymentDays} days");
    }
}
